/// GLFW key codes the SDK's own `kGlfwToLogicalKey` omits, so they are absent
/// from the generated table above and would produce no key event at all.
///
/// That table is the SDK's *legacy* `RawKeyEvent` mapping, which is only used
/// here as a convenient GLFW-code source; the modern `FlutterKeyEvent`
/// protocol takes the physical and logical ids straight from the embedder, so
/// a key the legacy map never covered is still perfectly reportable. Values
/// are the SDK's own `PhysicalKeyboardKey`/`LogicalKeyboardKey` constants.
///
/// GLFW's `F25` is deliberately absent: Flutter defines no `f25` key.
pub fn glfw_key_to_flutter_extra(key: i32) -> Option<(u64, u64)> {
    let pair = match key {
        281 => (0x0007_0047, 0x0010_0000_010c), // scroll lock
        313 => (0x0007_0073, 0x0010_0000_0818), // F24
        333 => (0x0007_0056, 0x0020_0000_022d), // numpad minus
        _ => return None,
    };
    Some(pair)
}

#[cfg(test)]
mod tests {
    use super::{glfw_key_to_flutter, glfw_key_to_flutter_extra};

    #[test]
    fn known_keys_match_flutter_constants() {
        // (GLFW key code, physical USB HID, Flutter logical) from the SDK.
        assert_eq!(glfw_key_to_flutter(65), Some((0x0007_0004, 0x0000_0061))); // A
        assert_eq!(glfw_key_to_flutter(32), Some((0x0007_002c, 0x0000_0020))); // space
        assert_eq!(glfw_key_to_flutter(257), Some((0x0007_0028, 0x1_0000_000d))); // enter
        assert_eq!(glfw_key_to_flutter(256), Some((0x0007_0029, 0x1_0000_001b))); // escape
        assert_eq!(glfw_key_to_flutter(340), Some((0x0007_00e1, 0x2_0000_0102))); // left shift
    }

    #[test]
    fn unmapped_key_is_none() {
        assert_eq!(glfw_key_to_flutter(-1), None);
        assert_eq!(glfw_key_to_flutter(99999), None);
    }

    /// The supplement exists because the SDK's GLFW table skips these three;
    /// if a regeneration ever starts covering them, the two tables would
    /// disagree and the supplement should be dropped instead.
    #[test]
    fn supplement_covers_only_what_the_generated_table_misses() {
        for key in [281, 313, 333] {
            assert_eq!(glfw_key_to_flutter(key), None, "glfw key {key}");
            assert!(glfw_key_to_flutter_extra(key).is_some(), "glfw key {key}");
        }
        assert_eq!(
            glfw_key_to_flutter_extra(333),
            Some((0x0007_0056, 0x0020_0000_022d))
        );
        // F25 has no Flutter logical key, and neither table may invent one.
        assert_eq!(glfw_key_to_flutter(314), None);
        assert_eq!(glfw_key_to_flutter_extra(314), None);
        // Keys the generated table does cover must not be duplicated here.
        for key in [32, 65, 257, 332, 334] {
            assert!(glfw_key_to_flutter(key).is_some(), "glfw key {key}");
            assert_eq!(glfw_key_to_flutter_extra(key), None, "glfw key {key}");
        }
    }
}
